#include <stdio.h>

typedef struct { int capacity; int tokens; int fill_rate; } TokenBucket;

void tb_init(TokenBucket *tb, int cap, int rate) {
    tb->capacity = cap; tb->tokens = cap; tb->fill_rate = rate;
}

int allow_request(TokenBucket *tb) {
    if (tb->tokens < tb->capacity) tb->tokens++;
    if (tb->tokens > 0) { tb->tokens--; return 1; }
    return 0;
}

int main() {
    TokenBucket tb;
    tb_init(&tb, 5, 1);
    for (int i = 1; i <= 8; i++) {
        printf("Req %d: %s\n", i, allow_request(&tb) ? "Allowed" : "Denied");
    }
    return 0;
}
